questionvariables.text:
perimeter : 2*rand_with_prohib(10,40,[]);      /* keep it even so the vertex width is a whole number */
Afun : w*(perimeter-2*w);
Aexpand : expand(Afun);
wvertex : -coeff(Aexpand,w,1)/(2*coeff(Aexpand,w,2));
ta : subst(w=wvertex,Afun);
wrong_vertexw : wvertex;                 /* gave the optimal WIDTH instead of the maximum AREA */
